const nav=[["overview","⌂"],["training","◎"],["mission","ϟ"],["science","✧"],["report","▤"]];
const persist=()=>{s.localUpdatedAt=Date.now();saveState(s);scheduleSync(s);},go=view=>{s.view=view;persist();render();window.scrollTo(0,0);};
function resources(values){return RESOURCES.map(r=>{const v=values[r.id],state=v<30?"low":v<70?"warning":"healthy";return'<div class="resource"><label>'+(ar()?r.ar:r.name)+'</label><div class="bar"><i class="'+state+'" style="width:'+v+'%"></i></div><b>'+v+'</b></div>';}).join("");}
function resourceSummary(values){const groups=[["power",local("ENERGY","الطاقة"),"⚡",values.power],["oxygen",local("OXYGEN","الأكسجين"),"◉",values.oxygen],["supplies",local("WATER & FOOD","المياه والغذاء"),"◈",Math.round((values.water+values.food)/2)],["shield",local("CREW PROTECTION","حماية الطاقم"),"🛡️",values.shield]];return '<div class="resource-summary">'+groups.map(([id,label,icon,value])=>'<div class="resource-tile"><span>'+icon+'</span><div><small>'+label+'</small><b>'+value+'%</b><div class="bar"><i class="'+(value<30?"low":value<70?"warning":"healthy")+'" style="width:'+value+'%"></i></div></div></div>').join("")+'</div>';}
function navHtml(mobile=false){return nav.map(([id,icon],i)=>'<button class="'+(mobile?"":"nav-item ")+(s.view===id?"active":"")+'" data-nav="'+id+'"><span class="'+(mobile?"":"nav-icon")+'">'+icon+'</span><span>'+t("nav")[i]+'</span></button>').join("");}
function spaceIntro(){return '<main class="space-intro" aria-label="'+local("Welcome to TECNOVA","مرحبًا بك في تكنوفا")+'"><div class="intro-stars"></div><div class="intro-nebula"></div><div class="intro-3d-world" aria-hidden="true"></div><div class="intro-planet intro-planet-blue"><span></span></div><div class="intro-planet intro-planet-pink"><span></span></div><div class="intro-saturn"><i></i><span></span></div><div class="intro-moon"></div><div class="intro-astronaut"><span class="astronaut-pack"></span><span class="astronaut-helmet"><i></i></span><span class="astronaut-body"></span><span class="astronaut-arm"></span><span class="astronaut-boot"></span></div><div class="intro-orbit intro-orbit-one"></div><div class="intro-orbit intro-orbit-two"></div><header class="intro-top"><div class="intro-logo"><span>✦</span><div><b>TECNOVA</b><small>JUNIOR SPACE EXPLORERS</small></div></div><button class="intro-language" data-action="language">'+(ar()?"EN · English":"عربي · العربية")+'</button></header><section class="intro-copy"><span class="intro-kicker"><i></i>'+local("YOUR NEXT ADVENTURE STARTS HERE","مغامرتك الجديدة بتبدأ من هنا")+'</span><h1>'+local("A little step for you.<br><em>A giant adventure in space.</em>","خطوة صغيرة منك...<br><em>ومغامرة كبيرة في الفضاء!</em>")+'</h1><p>'+local("Meet new planets, explore the Moon and become the commander of your own lunar outpost.","اكتشف كواكب جديدة، واستكشف سطح القمر، وكن قائد قاعدتك الفضائية!")+'</p><button class="intro-launch" data-action="intro-start"><span>🚀</span>'+local("LET'S EXPLORE","يلا نبدأ المغامرة")+'<b>↗</b></button><small class="intro-footnote">'+local("A playful 3D space-learning adventure · No VR headset needed","مغامرة تعليمية ثلاثية الأبعاد · لا تحتاج إلى نظارة VR")+'</small></section><button class="intro-skip" data-action="intro-skip" aria-label="'+local("Skip intro","تخطي المقدمة")+'">'+local("Skip intro","تخطي المقدمة")+'</button><div class="intro-bottom"><span>✦ '+local("DISCOVER","اكتشف")+'</span><span>◉ '+local("LEARN","تعلّم")+'</span><span>🚀 '+local("EXPLORE","استكشف")+'</span></div><div class="intro-credit">TECNOVA · LUNAR OUTPOST MISSION SURVIVAL</div></main>';}
function shell(content){const title=t("nav")[nav.findIndex(x=>x[0]===s.view)];return'<div class="shell '+(ar()?"rtl ":"")+(s.view==="overview"?"home-shell":"")+'"><aside class="sidebar"><div class="brand"><div class="brand-mark">◐</div><div><b>LUNAR OUTPOST</b><small>JUNIOR ASTRONAUT TRAINER</small></div></div><div class="nav-label">'+t("navLabel")+'</div><nav class="side-nav">'+navHtml()+'</nav><div class="grow"></div><div class="sidebar-box"><small>TRAINING PROGRESS</small><b>'+s.trainingDone.length+' / 4 '+(ar()?"وحدات مكتملة":"MODULES COMPLETE")+'</b><div class="track"><i style="width:'+(s.trainingDone.length/4*100)+'%"></i></div></div><div class="side-foot"><span>BUILD '+VERSION+'</span><button class="lang" data-action="language">EN / AR</button></div></aside><main class="main"><header class="topbar"><div class="crumb">'+t("commander")+' / <b>'+esc(title).toUpperCase()+'</b></div><div class="top-actions"><span class="commander-mini"><span class="commander-mini-avatar avatar-'+esc(s.commander?.avatar||"blue")+'"></span><b>'+esc(s.commander?.name||"Commander")+'</b></span><span class="status"><i></i>'+t("ready")+'</span><span class="cloud-status">'+(isCloudEnabled()?local("CLOUD SYNC READY","المزامنة السحابية جاهزة"):local("DEVICE SAVE","حفظ على الجهاز"))+'</span><button class="install" data-action="install" '+(installEvent?"":"hidden")+'>'+t("install")+'</button></div></header><section class="content">'+content+'<div class="footer">'+t("footer")+'</div></section><nav class="mobile-nav">'+navHtml(true)+'</nav></main></div>';}

function onboarding(){return '<main class="onboarding"><div class="onboard-brand"><span>✦</span><div><b>LUNAR OUTPOST</b><small>JUNIOR ASTRONAUT PROGRAM</small></div></div><section class="onboard-card"><p class="eyebrow">MISSION ACCESS / NEW COMMANDER</p><h1>'+local("Choose your astronaut","اختاري شخصية رائدة الفضاء")+'</h1><p class="onboard-sub">'+local("Create your commander profile and enter the lunar mission hub.","اعملي ملف القائد وادخلي مركز المهمات القمرية.")+'</p><label class="profile-label" for="commander-name">'+local("COMMANDER CALLSIGN","اسم القائد")+'</label><input id="commander-name" maxlength="18" placeholder="'+local("Your name","اسمك")+'" value="'+esc(s.commander?.name||"")+'"><div class="avatar-grid">'+[["blue","Astra"],["purple","Nova"],["gold","Sol"],["green","Luna"]].map(([id,name],i)=>'<button type="button" class="avatar-choice '+(selectedAvatar===id?"selected":"")+'" data-avatar="'+id+'"><span class="avatar-art avatar-'+id+'"></span><b>'+name+'</b><small>'+local("ASTRONAUT","رائد فضاء")+' 0'+(i+1)+'</small></button>').join("")+'</div><button class="primary onboard-enter" data-action="create-profile">'+local("ENTER MISSION CONTROL","دخول مركز التحكم")+' →</button><p class="onboard-privacy">'+local("A private guest profile. Cloud backup becomes available when the project server is connected.","ملف ضيف خاص. النسخ الاحتياطي السحابي يتاح بعد ربط خادم المشروع.")+'</p></section></main>';}
